export type EvidenceRecord = {
  id: string;
  candidateId: string;
  requirementId: string | null;
  claimKey: string;
  observedValue: string;
  sourceUrl: string;
  sourceKind: 'ZENODO' | 'GITHUB' | 'HUGGING_FACE';
